package filebrowser

import (
	"os"
	"testing"

	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-201 D3: a paste reaches the focused field of the browser (the filter
// bar, the create form's name) and fires no action (Rule 111).
func TestPasteReachesTheCreateFormName(t *testing.T) {
	tests := []struct{ name, paste, want string }{
		{"word", "new-dir", "new-dir"},
		{"with space", "x y", "x y"},
		{"multi-line", "a\nb", "a b"},
		{"action letters", "Dq?", "Dq?"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			dir := tree(t)
			m := openAt(t, dir)
			m, _ = press(t, m, keymap.New)
			if m.mode != modeCreating {
				t.Fatal("N must open the form")
			}
			m, cmd := step(t, m, testutil.Paste(tc.paste))

			if got := m.form.name.Value(); got != tc.want {
				t.Errorf("name = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
			if m.mode != modeCreating {
				t.Error("the paste left the creating mode")
			}
			if cmd != nil {
				for _, msg := range testutil.Msgs(cmd) {
					if _, ok := msg.(createFormSubmitMsg); ok {
						t.Error("the paste submitted the form")
					}
				}
			}
			if entries, _ := os.ReadDir(dir); len(entries) != 4 {
				t.Errorf("the directory holds %d entries, want the 4 it started with", len(entries))
			}
		})
	}
}

func TestPasteReachesTheFilterBar(t *testing.T) {
package setup

import (
	"testing"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-201 D3: a paste reaches the text field of the current wizard step,
// newlines become spaces, and nothing advances or goes back (Rule 111). Pasting
// into the URL field counts as touching it, like typing does.
func TestPasteReachesTheFocusedStepField(t *testing.T) {
	tests := []struct {
		name  string
		step  int
		paste string
		want  string
		read  func(m Model) string
	}{
		{"context name", stepContextName, "staging", "staging", func(m Model) string { return m.contextNameInput.Value() }},
		{"context name, multi-line", stepContextName, "a\nb", "a b", func(m Model) string { return m.contextNameInput.Value() }},
		{"context name, action letters", stepContextName, "Dq?:", "Dq?:", func(m Model) string { return m.contextNameInput.Value() }},
		{"forge URL", stepForgeURL, "https://git.internal", "https://git.internal", func(m Model) string { return m.forgeURLInput.Value() }},
		{"forge URL, multi-line", stepForgeURL, "a\nb", "a b", func(m Model) string { return m.forgeURLInput.Value() }},
		{"namespace", stepForgeNamespace, "team/sub", "team/sub", func(m Model) string { return m.forgeNamespaceInput.Value() }},
		{"token", stepForgeToken, "glpat-abc", "glpat-abc", func(m Model) string { return m.forgeTokenInput.Value() }},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			isolateHome(t)
			m := past(t, New(), "")
			m.step = tc.step
			m.updateFocus()
			m.contextNameInput.SetValue("")
			m.forgeURLInput.SetValue("")
			m.forgeURLTouched = false

			m = feed(t, m, testutil.Paste(tc.paste))

			if got := tc.read(m); got != tc.want {
				t.Errorf("field = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
			if m.step != tc.step {
				t.Errorf("step = %d after the paste, want %d", m.step, tc.step)
			}
			if tc.step == stepForgeURL && !m.forgeURLTouched {
				t.Error("pasting into the URL did not mark it as touched")
			}
		})
	}
}
package auth

import (
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-201 D3: a paste reaches the focused token field and fires no action
// (Rule 111). The multi-line row proves newlines become spaces in a one-line
// field and that the submit key is not fired by a pasted newline.
func TestPasteReachesTheFocusedTokenField(t *testing.T) {
	tests := []struct {
		name  string
		typed string
		paste string
		want  string
	}{
		{"plain", "", "glpat-abc", "glpat-abc"},
		{"with spaces", "", "x y", "x y"},
		{"appends to typed text", "ab", "cd", "abcd"},
		{"multi-line becomes spaces", "", "a\nb", "a b"},
		{"letters that are actions elsewhere", "", "Dq?:", "Dq?:"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			m := newTestModel(t, testConfig(), newFakeStorage())
			if tc.typed != "" {
				m = feed(t, m, testutil.Type(tc.typed)...)
			}
			m, cmd := step(t, m, testutil.Paste(tc.paste))

			if got := m.tokenInput.Value(); got != tc.want {
				t.Errorf("token field = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
			if m.authenticating {
				t.Error("the paste started a login")
			}
			if cmd != nil {
				if _, quit := cmd().(tea.QuitMsg); quit {
					t.Error("the paste quit the application")
				}
			}
		})
	}
}

